export function mergeGuiMentoriaCalendar(existing) {
  const posts = Array.isArray(existing) ? existing : [];
  const ids = new Set(posts.map(post => String(post?.id)));
  const names = new Set(posts.map(post => String(post?.title || '').trim().toLocaleLowerCase('pt-BR')));
  return [
    ...posts,
    ...GUI_MENTORIA_OCT2026_POSTS.filter(post => !ids.has(String(post.id)) && !names.has(post.title.trim().toLocaleLowerCase('pt-BR'))),
  ];
}

// Called only while loading the Gui posts from browser storage.
// Preserve existing edits, dates, statuses and user-created content.
// The migration marker stops deleted ideas from reappearing on every refresh.
export function addGuiMentoriaCalendarOnce(existing, storage) {
  if (!storage || storage.getItem(GUI_MENTORIA_OCT2026_KEY) === '1') return existing;
  const merged = mergeGuiMentoriaCalendar(existing);
  storage.setItem('guihub-posts', JSON.stringify(merged));
  storage.setItem(GUI_MENTORIA_OCT2026_KEY, '1');
  return merged;
}
